<?php admin_page_start('Support Ticket','support','SUPPORT TICKET','#'.(int)$ticket['id'],'',''.(string)$ticket['subject']); ?>
<?php if($message):?><div class="app-alert admin-alert success"><?=htmlspecialchars($message,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($error):?><div class="app-alert admin-alert danger"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?>
<section class="admin-stats"><article class="app-stat admin-stat"><div class="stat-label"><span class="stat-mark"></span>Customer</div><strong class="admin-stat-version"><?=htmlspecialchars((string)$ticket['username'],ENT_QUOTES,'UTF-8')?></strong><small>Customer #<?=(int)$ticket['user_id']?></small></article><article class="app-stat admin-stat"><div class="stat-label"><span class="stat-mark"></span>Status</div><strong class="admin-stat-version"><?=htmlspecialchars(strtoupper((string)$ticket['status']),ENT_QUOTES,'UTF-8')?></strong><small><?=htmlspecialchars(strtoupper((string)$ticket['category']),ENT_QUOTES,'UTF-8')?></small></article><article class="app-stat admin-stat"><div class="stat-label"><span class="stat-mark"></span>Recent orders</div><strong><?=count($orders)?></strong><small>Last five available</small></article></section>
<section class="admin-grid-2"><article class="app-panel admin-panel admin-card-pad"><p class="panel-kicker">CONVERSATION</p><h2><?=htmlspecialchars((string)$ticket['subject'],ENT_QUOTES,'UTF-8')?></h2><div class="admin-history-list"><?php foreach($messages as $m):?><div class="admin-history-item"><div><strong><?=$m['sender_is_admin']?'SUPPORT':htmlspecialchars((string)($m['username']??'CUSTOMER'),ENT_QUOTES,'UTF-8')?></strong><?=web_local_datetime($m['created_at']??null,'Unknown')?></div><?php if(!empty($m['message'])):?><p><?=nl2br(htmlspecialchars((string)$m['message'],ENT_QUOTES,'UTF-8'))?></p><?php endif;?><?php if(!empty($m['attachment_stored_name'])):?><small><a class="panel-link" href="<?=route_url('support-attachment.php')?>?id=<?=(int)$m['id']?>">Download <?=htmlspecialchars((string)$m['attachment_original_name'],ENT_QUOTES,'UTF-8')?> ↓</a></small><?php endif;?></div><?php endforeach;?></div></article><aside class="app-panel admin-panel admin-card-pad"><p class="panel-kicker">REPLY</p><h2>Support response</h2><form method="post" enctype="multipart/form-data" class="admin-section-mini"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$ticket['id']?>"><input type="hidden" name="action" value="reply"><label class="app-field admin-field"><span>Message</span><textarea name="message" rows="8" maxlength="8000"></textarea></label><label class="app-field admin-field"><span>Attachment</span><input type="file" name="diagnostics" accept=".jpg,.jpeg,.png,.webp,.pdf,.zip,.log,.txt,.json"></label><button class="app-button admin-button primary" type="submit">Send reply</button></form><hr class="admin-rule"><form method="post" class="admin-inline-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$ticket['id']?>"><input type="hidden" name="action" value="status"><label class="app-field admin-field"><span>Status</span><select name="status"><?php foreach(['open','waiting','closed'] as $v):?><option value="<?=$v?>" <?=$ticket['status']===$v?'selected':''?>><?=ucfirst($v)?></option><?php endforeach;?></select></label><button class="app-button admin-button secondary" type="submit">Update status</button></form><?php if($orders):?><hr class="admin-rule"><p class="panel-kicker">RECENT ORDERS</p><div class="admin-history-list"><?php foreach($orders as $o):?><div class="admin-history-item"><div><strong><?=htmlspecialchars((string)$o['order_number'],ENT_QUOTES,'UTF-8')?></strong><?=web_local_datetime($o['placed_at']??null,'—')?></div><p><?=htmlspecialchars(strtoupper((string)$o['status']),ENT_QUOTES,'UTF-8')?> · <?=number_format((float)$o['grand_total'],0)?> <?=htmlspecialchars((string)$o['currency'],ENT_QUOTES,'UTF-8')?></p></div><?php endforeach;?></div><?php endif;?></aside></section>
